while ! grep -q DONE-B ${RUNLOG_B:-/tmp/run-b.log}; do sleep 5; done
cd /home/claude/chuvadi-reader-platforms/tests/web-test; B=http://127.0.0.1:6090; S=http://127.0.0.1:5691; O=${OUT:-/tmp/out}
SL="Portal__IdleTimeout=00:00:40 Portal__ExpiryWarning=00:00:10 Portal__ExpiryCheckInterval=00:00:02 Portal__Workers__IdleStop=00:00:05 Portal__Workers__CheckInterval=00:00:02"
restart(){ kill $(cat /tmp/portal-6090.pid); sleep 1; rm -rf /dev/shm/chvd-6090; PUB=$PUB /tmp/start-portal.sh 6090 Gateway >/dev/null; }
restartS(){ kill $(cat /tmp/portal-5691.pid); sleep 1; rm -rf /dev/shm/chvd-5691; PUB=$PUB /tmp/start-portal.sh 5691 Gateway $SL >/dev/null; }
cnt(){ n=$1; shift; r=$(timeout 600 "$@" 2>&1 | grep -E "PASS|FAIL"); echo "$n: $(echo "$r" | grep -c PASS) pass, $(echo "$r" | grep -c FAIL) fail"; echo "$r" | grep FAIL | cut -c1-240; }
restartS; (cd /home/claude/wt-verify/tests/web-e2e; for i in 1 2 3; do cnt "comeback firefox run $i" python3 comeback.py $S /tmp/corpus/text-13.pdf /dev/shm/chvd-5691 --browser firefox; done)
for e in chromium firefox webkit; do restart; restartS; echo "== $e"; timeout 900 python3 mark_position.py $B $O $e > $O/mp-$e.txt 2>&1; cnt zoom_tools python3 zoom_tools.py $B $O $e; cnt close_card_probe python3 close_card_probe.py $B $S $O $e; cnt excel_p29 python3 excel_p29.py $B $O $e; cnt holds_probe python3 holds_probe.py $B /dev/shm/chvd-6090 $O $e; cnt encoding_probe python3 encoding_probe.py $B $O $e; cnt leave_prompt python3 leave_prompt.py $B $e; cnt reload_tabs python3 reload_tabs.py $B $S $e; cnt page_image_sec python3 page_image_sec.py $B $O $e; cnt verify_fixes python3 verify_fixes.py $B /tmp/portal-6090.log /tmp/corpus $O $e; timeout 400 python3 fidelity_check.py $B /tmp/portal-6090.log /tmp/fid $O $e /tmp/fid/fid.docx /tmp/fid/fid.xlsx /tmp/fid/fid-lo.docx /tmp/fid/fid-lo.xlsx 2>&1 | grep -oE '\[[a-z]+\] [a-z.-]+: .*exact' | sed 's/opened in [0-9]* ms, 0 page(s); //' | tr '\n' ' '; echo; timeout 280 python3 fidelity_check.py $B /tmp/portal-6090.log /tmp/fid $O $e /tmp/fid/fid.docx /tmp/fid/fid.xlsx 2>&1 | grep -iE "tokens|missing|of [0-9]+" | head -4 | cut -c1-160; done
restart; (export PLAYWRIGHT_BROWSERS_PATH=/tmp/oldpw-browsers PLAYWRIGHT_SKIP_VALIDATE_HOST_REQUIREMENTS=1; timeout 900 /tmp/oldpw/bin/python mark_position.py $B $O webkit > $O/mp-webkit17.txt 2>&1; cnt "zoom_tools webkit17" /tmp/oldpw/bin/python zoom_tools.py $B $O webkit)
restart; echo "== WT-18 / large"; timeout 900 python3 large_xlsx_check.py $B /tmp/bigx chromium 2>&1 | cut -c1-200
restart; echo "== sec_browser"; timeout 1100 python3 sec_browser.py $B /tmp/corpus $O/sec /tmp/portal-6090.log /dev/shm/chvd-6090 2>&1 | grep -E "^FAIL|pass,|watcher" | sed 's/.*\(watcher next-page [0-9]*\).*/\1/' | sort | uniq -c | sort -rn | head -12
for e in chromium firefox webkit; do restart; echo "cleanup_race $e (reload 1.5 s): $(timeout 600 python3 cleanup_race.py $B /dev/shm/chvd-6090 /tmp/portal-6090.log $e 5 1.5 2>&1 | grep SUMMARY)"; done
echo DONE-C
